  doc:    '<path d="M14 2.8H7a2 2 0 0 0-2 2v14.4a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V7.8z"/><path d="M14 2.8v5h5M9 13.2h6M9 16.8h4"/>',
  flag:   '<path d="M5.2 21.2V3.6h13l-2.6 4.2 2.6 4.2H5.2"/>'
