function svg(k) {
  return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">' + (ICONS[k] || '') + '</svg>';
}

// ---- Headline figures -------------------------------------------------
const KPIS = [
  { label: 'Open Issues',          dt: 'Issue',             f: { status: 'Open' },                          tone: 'warn', icon: 'issue' },
  { label: 'SLA Failed',           dt: 'Issue',             f: { agreement_status: 'Failed' },               tone: 'bad',  icon: 'clock' },
  { label: 'Open Warranty Claims', dt: 'Warranty Claim',    f: { status: 'Open' },                           tone: 'info', icon: 'shield' },
  { label: 'Visits Part. Done',    dt: 'Maintenance Visit', f: { completion_status: 'Partially Completed' }, tone: 'good', icon: 'clipboard' }
];

// ---- Check-box driven card (options can't be read from a Select) ------
const FIXED = [
  { title: 'Service Level Agreement', sub: 'Service Level Agreement', icon: 'doc', color: '#0f766e', dt: 'Service Level Agreement', rows: [
    { label: 'Enabled', f: { enabled: 1 } },
    { label: 'Disabled', f: { enabled: 0 } },
    { label: 'Default SLA', f: { default_service_level_agreement: 1 } },
    { label: 'Applies to Resolution', f: { apply_sla_for_resolution: 1 } }
  ]}
];

// ---- Select-field cards: options read live from the DocType ----------
const AUTO = [
  { title: 'Issues',               sub: 'Issue',                icon: 'issue',       dt: 'Issue',                field: 'status',              color: '#2563eb' },
  { title: 'SLA Status',           sub: 'Issue',                icon: 'clock',       dt: 'Issue',                field: 'agreement_status',    color: '#dc2626' },
  { title: 'Maintenance Schedule', sub: 'Maintenance Schedule', icon: 'calendar',    dt: 'Maintenance Schedule', field: 'status',              color: '#0d9488' },
  { title: 'Maintenance Visit',    sub: 'Maintenance Visit',    icon: 'clipboard',   dt: 'Maintenance Visit',    field: 'status',              color: '#ea580c' },
  { title: 'Maintenance Type',     sub: 'Maintenance Visit',    icon: 'gear',        dt: 'Maintenance Visit',    field: 'maintenance_type',    color: '#7c3aed' },
  { title: 'Visit Completion',     sub: 'Maintenance Visit',    icon: 'check',       dt: 'Maintenance Visit',    field: 'completion_status',   color: '#0891b2' },
  { title: 'Warranty Claim',       sub: 'Warranty Claim',       icon: 'shield',      dt: 'Warranty Claim',       field: 'status',              color: '#16a34a' },
  { title: 'Warranty / AMC',       sub: 'Warranty Claim',       icon: 'shieldcheck', dt: 'Warranty Claim',       field: 'warranty_amc_status', color: '#d97706' }
];

// ---- Link-field cards: rows read live from the master doctype --------
const LINKED = [
  { title: 'Issues by Type', sub: 'Issue Type', icon: 'tag', dt: 'Issue', field: 'issue_type', master: 'Issue Type', color: '#4f46e5' }
];

const WIDE = { title: 'Issues by Priority', sub: 'Issue Priority', icon: 'flag', dt: 'Issue', field: 'priority', master: 'Issue Priority', color: '#9333ea' };

const kpiBox = root_element.querySelector('.sdx-kpis');
const grid   = root_element.querySelector('.sdx-grid');
const wide   = root_element.querySelector('.sdx-wide');

function tone_for(label) {
  const l = String(label).toLowerCase().trim();
  if (l === 'low') { return 'good'; }
  if (l === 'medium') { return 'info'; }
  if (l === 'high') { return 'warn'; }
  if (l === 'urgent' || l === 'critical') { return 'bad'; }
  if (l.indexOf('partial') > -1 || l.indexOf('unschedul') > -1) { return 'warn'; }
  if (l.indexOf('out of') > -1 || l.indexOf('cancel') > -1 || l.indexOf('reject') > -1 || l.indexOf('fail') > -1 || l.indexOf('breakdown') > -1 || l.indexOf('disabled') > -1) { return 'bad'; }
  if (l.indexOf('complet') > -1 || l.indexOf('resolv') > -1 || l.indexOf('closed') > -1 || l.indexOf('fulfill') > -1 || l.indexOf('under ') > -1 || l.indexOf('enabled') > -1) { return 'good'; }
  if (l.indexOf('progress') > -1 || l.indexOf('replied') > -1 || l.indexOf('submitted') > -1 || l.indexOf('schedul') > -1 || l.indexOf('default') > -1) { return 'info'; }
  if (l.indexOf('open') > -1 || l.indexOf('hold') > -1 || l.indexOf('due') > -1 || l.indexOf('pending') > -1 || l.indexOf('applies') > -1) { return 'warn'; }
  return 'idle';
}

function count(dt, filters) {
  return frappe.db.count(dt, filters ? { filters: filters } : undefined)
    .then(function(v) { return v || 0; })
    .catch(function() { return 0; });
}

function status_options(dt, fieldname) {
  return new Promise(function(resolve) {
    frappe.model.with_doctype(dt, function() {
      var df = null;
      try { df = frappe.meta.get_docfield(dt, fieldname); } catch (e) { df = null; }
      if (!df || !df.options) { resolve([]); return; }
      resolve(String(df.options).split('\n').map(function(s) { return s.trim(); }).filter(function(s) { return s.length; }));
    });
  });
}

function link_options(master) {
  return frappe.db.get_list(master, { fields: ['name'], limit: 40, order_by: 'name asc' })
    .then(function(rows) { return (rows || []).map(function(r) { return r.name; }); })
    .catch(function() { return []; });
}

function to_rows(field, opts) {
  return opts.map(function(o) {
    var f = {}; f[field] = o;
    return { label: o, f: f };
  });
}

function esc(s) { return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }

// ---- KPI strip --------------------------------------------------------
function paint_kpis() {
  kpiBox.innerHTML = KPIS.map(function(k) {
    return '<div class="sdx-kpi t-' + k.tone + '">' +
           '<div class="sdx-kpi-ico">' + svg(k.icon) + '</div>' +
           '<div class="sdx-kpi-body"><div class="sdx-kpi-val">\u00b7\u00b7</div>' +
           '<div class="sdx-kpi-lbl">' + esc(k.label) + '</div></div></div>';
  }).join('');
  const els = kpiBox.querySelectorAll('.sdx-kpi');
  KPIS.forEach(function(k, i) {
    els[i].addEventListener('click', function() { frappe.set_route('List', k.dt, k.f); });
    count(k.dt, k.f).then(function(v) {
      els[i].querySelector('.sdx-kpi-val').textContent = v;
      if (!v) { els[i].classList.add('is-zero'); }
    });
  });
}

// ---- Card shell -------------------------------------------------------
function shell(card, container) {
  const el = document.createElement('div');
  el.className = 'sdx-card';
  el.style.setProperty('--accent', card.color);
  el.innerHTML =
    '<div class="sdx-card-top">' +
      '<div class="sdx-ico">' + svg(card.icon) + '</div>' +
      '<div class="sdx-name">' + esc(card.title) + '<span>' + esc(card.sub || card.dt) + '</span></div>' +
      '<div class="sdx-tot">\u00b7\u00b7</div>' +
    '</div>' +
    '<div class="sdx-stack"></div>' +
    '<div class="sdx-rows"><div class="sdx-skel"><i></i><i></i><i></i></div></div>';
  container.appendChild(el);
  el.querySelector('.sdx-tot').addEventListener('click', function() { frappe.set_route('List', card.dt); });
  return el;
}

function paint_rows(el, card, rows) {
  const holder = el.querySelector('.sdx-rows');
  const stack  = el.querySelector('.sdx-stack');

  if (!rows.length) {
    holder.innerHTML = '<div class="sdx-empty">No options defined yet</div>';
    stack.classList.add('is-empty');
  } else {
    holder.innerHTML = rows.map(function(r) {
      return '<div class="sdx-row t-' + tone_for(r.label) + '">' +
             '<span class="sdx-dot"></span>' +
             '<span class="sdx-lbl">' + esc(r.label) + '</span>' +
             '<span class="sdx-val">\u00b7\u00b7</span></div>';
    }).join('');

    const rowEls = holder.querySelectorAll('.sdx-row');
    rows.forEach(function(r, i) {
      rowEls[i].addEventListener('click', function() { frappe.set_route('List', card.dt, r.f); });
    });

    Promise.all(rows.map(function(r) { return count(card.dt, r.f); })).then(function(vals) {
      const sum = vals.reduce(function(a, b) { return a + b; }, 0);
      vals.forEach(function(v, i) {
        rowEls[i].querySelector('.sdx-val').textContent = v;
        if (!v) { rowEls[i].classList.add('is-zero'); }
      });
      if (!sum) { stack.classList.add('is-empty'); return; }
      stack.innerHTML = vals.map(function(v, i) {
        if (!v) { return ''; }
        return '<i class="t-' + tone_for(rows[i].label) + '" style="flex:' + v + '" title="' + esc(rows[i].label) + ': ' + v + '"></i>';
      }).join('');
    });
  }

  count(card.dt).then(function(v) { el.querySelector('.sdx-tot').textContent = v; });
}

// ---- Wide card: proportional bars ------------------------------------
function paint_wide() {
  wide.innerHTML = '';
  const el = document.createElement('div');
  el.className = 'sdx-card sdx-wide-card';
  el.style.setProperty('--accent', WIDE.color);
  el.innerHTML =
    '<div class="sdx-card-top">' +
      '<div class="sdx-ico">' + svg(WIDE.icon) + '</div>' +
      '<div class="sdx-name">' + esc(WIDE.title) + '<span>' + esc(WIDE.sub) + '</span></div>' +
      '<div class="sdx-tot">\u00b7\u00b7</div>' +
    '</div><div class="sdx-bars"><div class="sdx-skel"><i></i><i></i><i></i></div></div>';
  wide.appendChild(el);
  el.querySelector('.sdx-tot').addEventListener('click', function() { frappe.set_route('List', WIDE.dt); });

  const bars = el.querySelector('.sdx-bars');
  count(WIDE.dt).then(function(v) { el.querySelector('.sdx-tot').textContent = v; });

  link_options(WIDE.master).then(function(opts) {
    if (!opts.length) { bars.innerHTML = '<div class="sdx-empty">No priorities defined yet</div>'; return; }
    bars.innerHTML = opts.map(function(o) {
      return '<div class="sdx-barrow t-' + tone_for(o) + '">' +
             '<span class="sdx-barlbl">' + esc(o) + '</span>' +
             '<span class="sdx-track"><i style="width:0%"></i></span>' +
             '<span class="sdx-barval">\u00b7\u00b7</span></div>';
    }).join('');
    const rowEls = bars.querySelectorAll('.sdx-barrow');
    opts.forEach(function(o, i) {
      var f = {}; f[WIDE.field] = o;
      rowEls[i].addEventListener('click', function() { frappe.set_route('List', WIDE.dt, f); });
    });
    Promise.all(opts.map(function(o) {
      var f = {}; f[WIDE.field] = o; return count(WIDE.dt, f);
    })).then(function(vals) {
      const max = Math.max.apply(null, vals.concat([1]));
      vals.forEach(function(v, i) {
        rowEls[i].querySelector('.sdx-barval').textContent = v;
        rowEls[i].querySelector('.sdx-track i').style.width = Math.round((v / max) * 100) + '%';
        if (!v) { rowEls[i].classList.add('is-zero'); }
      });
    });
  });
}

// ---- Build ------------------------------------------------------------
function render() {
  kpiBox.innerHTML = '';
  grid.innerHTML = '';
  wide.innerHTML = '';

  paint_kpis();

  FIXED.forEach(function(card) {
    paint_rows(shell(card, grid), card, card.rows);
  });

  AUTO.forEach(function(card) {
    const el = shell(card, grid);
    status_options(card.dt, card.field).then(function(opts) {
      paint_rows(el, card, to_rows(card.field, opts));
    });
  });

  LINKED.forEach(function(card) {
    const el = shell(card, grid);
    link_options(card.master).then(function(opts) {
      paint_rows(el, card, to_rows(card.field, opts));
    });
  });

  paint_wide();
}

root_element.querySelector('.sdx-refresh').addEventListener('click', function() {
  const b = this;
  b.classList.add('is-spinning');
  render();
  setTimeout(function() { b.classList.remove('is-spinning'); }, 700);
});

render();

style:
.sdx { padding: 2px 0 10px; --good: #16a34a; --warn: #ea580c; --info: #2563eb; --bad: #dc2626; --idle: #94a3b8; }
.sdx .t-good { --tone: var(--good); --tint: rgba(22,163,74,.12); }
.sdx .t-warn { --tone: var(--warn); --tint: rgba(234,88,12,.12); }
.sdx .t-info { --tone: var(--info); --tint: rgba(37,99,235,.12); }
.sdx .t-bad  { --tone: var(--bad);  --tint: rgba(220,38,38,.12); }
.sdx .t-idle { --tone: var(--idle); --tint: rgba(148,163,184,.14); }

/* header */
.sdx-head { display: flex; align-items: flex-end; justify-content: space-between; gap: 16px; margin-bottom: 20px; }
.sdx-h1 { font-size: 24px; font-weight: 650; letter-spacing: -0.02em; line-height: 1.15; }
.sdx-h2 { font-size: 12.5px; color: var(--text-muted, #6b7280); margin-top: 4px; }
.sdx-refresh { display: inline-flex; align-items: center; gap: 7px; border: 1px solid var(--border-color, #e5e7eb); background: var(--card-bg, #fff); color: var(--text-muted, #6b7280); border-radius: 8px; padding: 7px 12px; font-size: 12.5px; font-weight: 500; cursor: pointer; transition: all .15s ease; flex: none; }
.sdx-refresh:hover { color: var(--text-color, #111827); border-color: var(--text-muted, #9ca3af); }
.sdx-refresh svg { width: 14px; height: 14px; }
.sdx-refresh.is-spinning svg { animation: sdx-spin .7s linear; }
@keyframes sdx-spin { to { transform: rotate(360deg); } }

/* KPI strip */
.sdx-kpis { display: grid; grid-template-columns: repeat(auto-fit, minmax(190px, 1fr)); gap: 12px; margin-bottom: 16px; }
.sdx-kpi { display: flex; align-items: center; gap: 13px; padding: 15px 16px; border-radius: 13px; background: var(--tint); border: 1px solid transparent; cursor: pointer; transition: transform .14s ease, box-shadow .14s ease; }
.sdx-kpi:hover { transform: translateY(-2px); box-shadow: 0 6px 18px -8px rgba(0,0,0,.28); }
.sdx-kpi-ico { width: 38px; height: 38px; border-radius: 10px; display: grid; place-items: center; background: var(--card-bg, #fff); color: var(--tone); flex: none; }
.sdx-kpi-ico svg { width: 19px; height: 19px; }
.sdx-kpi-val { font-size: 25px; font-weight: 700; line-height: 1.05; color: var(--tone); font-variant-numeric: tabular-nums; }
.sdx-kpi-lbl { font-size: 11.5px; font-weight: 500; color: var(--text-muted, #6b7280); margin-top: 2px; }
.sdx-kpi.is-zero { opacity: .62; }

/* card grid */
.sdx-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(268px, 1fr)); gap: 14px; }
.sdx-card { background: var(--card-bg, #fff); border: 1px solid var(--border-color, #e5e7eb); border-radius: 14px; padding: 15px 16px 13px; display: flex; flex-direction: column; transition: box-shadow .16s ease, border-color .16s ease; }
.sdx-card:hover { box-shadow: 0 8px 24px -14px rgba(0,0,0,.32); border-color: var(--accent); }

.sdx-card-top { display: flex; align-items: center; gap: 10px; }
.sdx-ico { width: 30px; height: 30px; border-radius: 9px; display: grid; place-items: center; color: var(--accent); background: var(--accent); flex: none; }
.sdx-ico svg { width: 16px; height: 16px; color: var(--card-bg, #fff); }
.sdx-name { flex: 1; min-width: 0; font-size: 13.5px; font-weight: 600; line-height: 1.25; color: var(--text-color, #111827); }
.sdx-name span { display: block; font-size: 10.5px; font-weight: 500; color: var(--text-muted, #9ca3af); letter-spacing: .02em; margin-top: 1px; }
.sdx-tot { font-size: 22px; font-weight: 700; color: var(--accent); font-variant-numeric: tabular-nums; cursor: pointer; line-height: 1; }

/* distribution stack */
.sdx-stack { display: flex; gap: 2px; height: 5px; border-radius: 99px; overflow: hidden; margin: 13px 0 11px; background: var(--fg-hover-color, #f1f2f4); }
.sdx-stack i { background: var(--tone); border-radius: 99px; min-width: 3px; }
.sdx-stack.is-empty { opacity: .45; }

/* rows */
.sdx-rows { flex: 1; }
.sdx-row { display: flex; align-items: center; gap: 9px; padding: 6px 7px; margin: 0 -7px; font-size: 12.8px; cursor: pointer; border-radius: 7px; transition: background .12s ease; }
.sdx-row:hover { background: var(--fg-hover-color, #f3f4f6); }
.sdx-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--tone); flex: none; box-shadow: 0 0 0 3px var(--tint); }
.sdx-lbl { color: var(--text-color, #374151); flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.sdx-val { font-weight: 650; font-variant-numeric: tabular-nums; color: var(--text-color, #111827); }
.sdx-row.is-zero { opacity: .45; }
.sdx-empty { font-size: 12px; color: var(--text-muted, #9ca3af); padding: 8px 0; }

/* loading skeleton */
.sdx-skel i { display: block; height: 9px; border-radius: 5px; margin: 9px 0; background: var(--fg-hover-color, #eef0f2); animation: sdx-pulse 1.2s ease-in-out infinite; }
.sdx-skel i:nth-child(2) { width: 78%; animation-delay: .12s; }
.sdx-skel i:nth-child(3) { width: 55%; animation-delay: .24s; }
@keyframes sdx-pulse { 0%,100% { opacity: 1; } 50% { opacity: .45; } }

/* wide card */
.sdx-wide { margin-top: 14px; }
.sdx-bars { margin-top: 15px; display: grid; gap: 11px; }
.sdx-barrow { display: grid; grid-template-columns: 120px 1fr 46px; align-items: center; gap: 12px; cursor: pointer; padding: 3px 6px; margin: 0 -6px; border-radius: 7px; transition: background .12s ease; }
.sdx-barrow:hover { background: var(--fg-hover-color, #f3f4f6); }
.sdx-barlbl { font-size: 12.8px; font-weight: 550; color: var(--text-color, #374151); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.sdx-track { height: 9px; border-radius: 99px; background: var(--fg-hover-color, #f1f2f4); overflow: hidden; }
.sdx-track i { display: block; height: 100%; border-radius: 99px; background: var(--tone); transition: width .45s cubic-bezier(.4,0,.2,1); }
.sdx-barval { font-size: 14px; font-weight: 700; text-align: right; font-variant-numeric: tabular-nums; color: var(--tone); }
.sdx-barrow.is-zero { opacity: .45; }

@media (max-width: 560px) {
  .sdx-barrow { grid-template-columns: 92px 1fr 38px; gap: 9px; }
  .sdx-h1 { font-size: 21px; }
}
